// 1. 领域事件：不可变、用过去时命名、自带 eventId
public class OrderCreatedEvent {
    private final String orderId;
    private final String customerId;
    private final BigDecimal totalAmount;
    private final LocalDateTime occurredAt;
    private final String eventId;

    public OrderCreatedEvent(String orderId, String customerId, BigDecimal total) {
        this.orderId = orderId;
        this.customerId = customerId;
        this.totalAmount = total;
        this.occurredAt = LocalDateTime.now();
        this.eventId = UUID.randomUUID().toString();
    }
}

// 2. 业务聚合：先写库再写 outbox，单事务保证「状态变更 + 事件」原子
@Component
public class OrderDomainService {
    private final OrderRepository orderRepository;
    private final OutboxRepository outboxRepository;

    @Transactional
    public OrderId createOrder(CreateOrderCmd cmd) {
        Order order = Order.create(cmd);
        orderRepository.save(order);
        OrderCreatedEvent event = new OrderCreatedEvent(
            order.getId(), order.getCustomerId(), order.getTotalAmount()
        );
        outboxRepository.save(event);
        return order.getId();
    }
}

// 3. Outbox Relay：定时把 outbox 表里未发布的事件投递到 Kafka
@Component
public class OutboxRelay {
    private final OutboxRepository outboxRepository;
    private final KafkaTemplate<String, String> kafkaTemplate;

    @Scheduled(fixedDelay = 100)
    public void relay() {
        List<OutboxRow> batch = outboxRepository.findUnpublished(100);
        for (OutboxRow row : batch) {
            kafkaTemplate.send("order-events", row.getAggregateId(), row.getPayload())
                .whenComplete((r, ex) -> {
                    if (ex == null) {
                        outboxRepository.markPublished(row.getEventId());
                    }
                });
        }
    }
}

// 4. 幂等消费：事件ID + 去重表
@Component
public class IdempotentInventoryListener {
    private final ProcessedEventRepository processedRepo;

    @KafkaListener(topics = "order-events", groupId = "inventory")
    public void onEvent(OrderCreatedEvent event) {
        if (processedRepo.exists(event.getEventId())) {
            return;
        }
        inventoryService.deduct(event.getOrderId(), event.getItems());
        processedRepo.markProcessed(event.getEventId());
    }
}

// 5. 失败处理：Kafka errorHandler 配置重试 + 死信队列
@Component
public class RetryableOrderListener {
    @KafkaListener(
        topics = "order-events",
        groupId = "notification",
        errorHandler = "kafkaErrorHandler"
    )
    public void onEvent(OrderCreatedEvent event) {
        notificationService.send(event.getCustomerId(), "下单成功");
    }
}

// 6. Saga 补偿：扣库存失败时发出反向事件
@Component
public class OrderSagaHandler {
    private final ApplicationEventPublisher eventPublisher;

    @EventListener
    public void onOrderCreated(OrderCreatedEvent event) {
        try {
            inventoryService.deduct(event.getOrderId(), event.getItems());
        } catch (InsufficientStockException e) {
            eventPublisher.publishEvent(
                new InventoryDeductFailedEvent(event.getOrderId(), e.getMessage())
            );
        }
    }
}
